)

const MOD = 998244353

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)

	// Precompute factorials and inverse factorials up to 2n
	maxN := 2 * n
	fact := make([]int, maxN+1)
	invFact := make([]int, maxN+1)
	fact[0] = 1
	for i := 1; i <= maxN; i++ {
		fact[i] = fact[i-1] * i % MOD
	}
	invFact[maxN] = modInv(fact[maxN], MOD)
	for i := maxN - 1; i >= 0; i-- {
		invFact[i] = invFact[i+1] * (i + 1) % MOD
	}

	// Precompute powers of 2
	pow2 := make([]int, maxN+1)
	pow2[0] = 1
	for i := 1; i <= maxN; i++ {
		pow2[i] = pow2[i-1] * 2 % MOD
	}

	// Precompute inverse powers of 2
	invPow2 := make([]int, maxN+1)
	invPow2[0] = 1
	inv2 := modInv(2, MOD)
	for i := 1; i <= maxN; i++ {
		invPow2[i] = invPow2[i-1] * inv2 % MOD
	}

	// Calculate the sum of beauty over all valid arrangements
	result := 0
	for k := 0; k <= n; k++ {
		// Number of ways to choose k pairs that are symmetric (opposite)
		ways := comb(n, k, fact, invFact)
		// Number of ways to arrange the remaining n-k pairs
		arrangements := fact[2*(n-k)] * invFact[n-k] % MOD
		// Each arrangement contributes (2^(n-k)) to the beauty
		beauty := pow2[n-k]
		// Total contribution for this k
		contribution := ways * arrangements % MOD
		contribution = contribution * beauty % MOD
		result = (result + contribution) % MOD
	}

	fmt.Println(result)
}

// comb calculates C(n, k) using precomputed factorials and inverse factorials
func comb(n, k int, fact, invFact []int) int {
	if k < 0 || k > n {
		return 0
	}
	return fact[n] * invFact[k] % MOD * invFact[n-k] % MOD
}

// modInv calculates the modular inverse of a under modulo m using Fermat's little theorem
func modInv(a, m int) int {
	return powMod(a, m-2, m)
}

// powMod calculates (base^exponent) % mod
func powMod(base, exponent, mod int) int {
	result := 1
	base = base % mod
	for exponent > 0 {
		if exponent%2 == 1 {
			result = (result * base) % mod
		}
		exponent = exponent >> 1
		base = (base * base) % mod
	}
	return result
}
